-- Phase 94: Security Operations Center control plane.
-- Auth, Audit, Observability, Incident Management, NOC, Identity Governance, Policy Engine and ActionEngine remain canonical.
-- quality: allow-nonconcurrent-index reason=new-empty-soc-tables-and-compatible-security-events-expansion

create type public.security_soc_context as enum('platform_soc','tenant_soc');

alter table public.plans add column if not exists security_operations_center_enabled boolean not null default false,add column if not exists security_detection_engine_enabled boolean not null default false,add column if not exists security_investigation_workbench_enabled boolean not null default false,add column if not exists security_response_orchestration_enabled boolean not null default false,add column if not exists security_threat_hunting_enabled boolean not null default false,add column if not exists security_ai_assistance_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists security_operations_center_enabled boolean not null default false,add column if not exists security_detection_engine_enabled boolean not null default false,add column if not exists security_investigation_workbench_enabled boolean not null default false,add column if not exists security_response_orchestration_enabled boolean not null default false,add column if not exists security_threat_hunting_enabled boolean not null default false,add column if not exists security_ai_assistance_enabled boolean not null default false;

-- Reuse and expand Phase 25 security_events instead of creating a second event store.
alter table public.security_events drop constraint if exists security_events_event_type_check;
alter table public.security_events add constraint security_events_event_type_check check(event_type in('suspicious_login','brute_force','mfa_disabled','api_key_abuse','repeated_permission_denied','webhook_signature_failure','unusual_export','session_hijack_suspected','new_device','mfa_reset','backup_failed','restore_test_overdue','secret_rotation_due','auth','session','mfa','privilege','access_change','data_access','data_export','api','webhook','integration','config_change','policy_change','feature_change','service_account','vendor_access','audit','security_control','automation','AI_action','infrastructure','custom'));
alter table public.security_events add column if not exists soc_context public.security_soc_context,add column if not exists source_domain text,add column if not exists source_ref text,add column if not exists source_event_id text,add column if not exists actor_identity_ref text,add column if not exists target_entity_type text,add column if not exists target_entity_ref text,add column if not exists tenant_scope text,add column if not exists store_scope text,add column if not exists severity_hint text,add column if not exists event_time timestamptz,add column if not exists ingest_time timestamptz not null default now(),add column if not exists source_ip_ref text,add column if not exists session_ref text,add column if not exists device_ref text,add column if not exists metadata_ref text,add column if not exists event_quality text not null default 'unknown',add column if not exists dedup_key text;
alter table public.security_events add constraint security_events_quality_check check(event_quality in('authoritative','derived','reconstructed','partial','unknown'));
alter table public.security_events add constraint security_events_soc_scope_check check(soc_context is null or soc_context='platform_soc' or organization_id is not null);

create table public.security_soc_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,context public.security_soc_context not null,permission_key text not null,scope_refs text[] not null default '{}',active boolean not null default true,granted_at timestamptz not null default now(),unique(organization_id,user_id,context,permission_key));
create table public.security_event_sources(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,source_key text not null,source_domain text not null,source_type text not null check(source_type in('auth_log','audit_event','API_gateway','WAF','application_event','observability','IAM','identity_governance','integration','provider_webhook','security_tool','cloud_event','custom')),owner_ref text not null,schema_ref text not null,freshness_requirement interval not null,sensitivity text not null check(sensitivity in('internal','confidential','restricted','critical')),enabled boolean not null default true,status text not null default 'healthy' check(status in('healthy','degraded','stale','disabled','unknown')),last_event_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context='tenant_soc' and organization_id is not null)or(context='platform_soc' and organization_id is null)),unique(context,organization_id,source_key));
create table public.security_source_health(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.security_event_sources(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,status text not null check(status in('healthy','degraded','stale','disabled','unknown')),ingestion_lag_seconds bigint,parse_failures bigint not null default 0,dropped_events bigint not null default 0,schema_compatible boolean,last_checked_at timestamptz not null default now(),details jsonb not null default '{}');

create table public.security_detection_rules(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,rule_key text not null,name text not null,description text not null,detection_type text not null check(detection_type in('threshold','sequence','correlation','anomaly_baseline','impossible_state','known_bad_pattern_internal','policy_violation','control_failure','custom_safe')),severity text not null check(severity in('info','low','medium','high','critical')),risk_context jsonb not null default '{}',scope jsonb not null default '{}',status text not null default 'draft' check(status in('draft','testing','pilot','active','deprecated','retired')),owner_ref text not null,current_version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context='tenant_soc' and organization_id is not null)or(context='platform_soc' and organization_id is null)),unique(context,organization_id,rule_key));
create table public.security_detection_rule_versions(id uuid primary key default gen_random_uuid(),rule_id uuid not null references public.security_detection_rules(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,version integer not null check(version>0),rule_definition jsonb not null,data_requirements jsonb not null default '[]',suppression_policy jsonb not null default '{}',evaluator_version text not null,change_reason text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(rule_id,version));
create table public.security_detection_test_runs(id uuid primary key default gen_random_uuid(),rule_version_id uuid not null references public.security_detection_rule_versions(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,test_mode text not null check(test_mode in('synthetic','historical_replay','known_benign','confirmed_incident')),window_start timestamptz,window_end timestamptz,matched_event_refs jsonb not null default '[]',false_positive_candidates jsonb not null default '[]',missing_data jsonb not null default '[]',expected_coverage jsonb not null default '{}',status text not null check(status in('passed','failed','inconclusive')),production_side_effects boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.security_detection_coverage(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,coverage_type text not null check(coverage_type in('critical_service','privileged_entitlement','data_classification','integration','vendor_access','API_surface')),entity_ref text not null,rule_id uuid references public.security_detection_rules(id) on delete set null,source_id uuid references public.security_event_sources(id) on delete set null,state text not null check(state in('covered','partial','gap','degraded','unknown')),evidence_ref text,last_assessed_at timestamptz not null default now(),unique(context,organization_id,coverage_type,entity_ref,rule_id));
create table public.security_detection_matches(id uuid primary key default gen_random_uuid(),rule_version_id uuid not null references public.security_detection_rule_versions(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,match_fingerprint text not null,event_refs jsonb not null,matched_at timestamptz not null default now(),confidence text not null check(confidence in('low','medium','high')),explanation jsonb not null,limitations jsonb not null default '[]',unique(rule_version_id,match_fingerprint));

create table public.security_correlated_events(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,title text not null,scope jsonb not null,severity text not null check(severity in('info','low','medium','high','critical')),confidence text not null check(confidence in('low','medium','high')),signal_count integer not null default 0,detection_count integer not null default 0,first_seen timestamptz not null,last_seen timestamptz not null,related_identity_refs text[] not null default '{}',related_service_refs text[] not null default '{}',related_change_refs text[] not null default '{}',incident_ref uuid references public.operational_incidents(id) on delete set null,status text not null default 'active' check(status in('active','investigating','contained','resolved','benign','archived')),created_at timestamptz not null default now());
create table public.security_correlation_event_links(correlated_event_id uuid not null references public.security_correlated_events(id) on delete cascade,security_event_id uuid not null references public.security_events(id) on delete restrict,link_reason text not null,created_at timestamptz not null default now(),primary key(correlated_event_id,security_event_id));
create table public.security_alerts(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,detection_rule_version_id uuid not null references public.security_detection_rule_versions(id) on delete restrict,detection_match_id uuid references public.security_detection_matches(id) on delete set null,correlated_event_id uuid references public.security_correlated_events(id) on delete set null,severity text not null check(severity in('info','low','medium','high','critical')),priority text not null check(priority in('P1','P2','P3','P4')),status text not null default 'new' check(status in('new','acknowledged','triage','investigating','contained','resolved','closed','suppressed')),title text not null,summary text not null,explanation jsonb not null,limitations jsonb not null default '[]',fingerprint text not null,detected_at timestamptz not null default now(),first_seen timestamptz not null default now(),last_seen timestamptz not null default now(),assigned_to uuid references auth.users(id),acknowledged_at timestamptz,disposition text check(disposition in('confirmed_security_incident','benign_expected_activity','false_positive','policy_violation','control_failure','suspicious_unconfirmed','duplicate','insufficient_evidence')),closed_at timestamptz,created_at timestamptz not null default now(),unique(context,organization_id,fingerprint));
create table public.security_alert_suppressions(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,rule_id uuid references public.security_detection_rules(id) on delete cascade,reason_type text not null check(reason_type in('known_test','approved_change','expected_automation','duplicate_pattern','temporary_exception')),reason text not null,scope jsonb not null,owner_ref text not null,approval_ref text,starts_at timestamptz not null default now(),expires_at timestamptz not null,status text not null default 'active' check(status in('requested','active','expired','revoked','rejected')),created_at timestamptz not null default now(),check(expires_at>starts_at));

create table public.security_investigations(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,title text not null,status text not null default 'open' check(status in('open','triage','investigating','containment','monitoring','closed')),severity text not null check(severity in('info','low','medium','high','critical')),owner_ref text not null,investigation_type text not null check(investigation_type in('identity','API','integration','data_access','privilege','vendor','infrastructure','automation','AI','multi_domain')),containment_state text not null default 'none' check(containment_state in('none','partial','contained','monitoring','released')),started_at timestamptz not null default now(),completed_at timestamptz,conclusion text,disposition text check(disposition in('confirmed_security_incident','benign_expected_activity','false_positive','policy_violation','control_failure','suspicious_unconfirmed','duplicate','insufficient_evidence')),incident_ref uuid references public.operational_incidents(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.security_investigation_alerts(investigation_id uuid not null references public.security_investigations(id) on delete cascade,alert_id uuid not null references public.security_alerts(id) on delete restrict,created_at timestamptz not null default now(),primary key(investigation_id,alert_id));
create table public.security_investigation_timeline(id bigint generated always as identity primary key,investigation_id uuid not null references public.security_investigations(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,event_time timestamptz not null,source_domain text not null,source_ref text not null,actor_ref text,target_ref text,action text not null,result text,evidence_quality text not null check(evidence_quality in('authoritative','derived','reconstructed','partial','unknown')),summary text not null,created_at timestamptz not null default now());
create table public.security_evidence_refs(id uuid primary key default gen_random_uuid(),investigation_id uuid references public.security_investigations(id) on delete cascade,alert_id uuid references public.security_alerts(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,evidence_type text not null check(evidence_type in('audit_event','auth_event','trace_log','identity_grant','change','policy_decision','integration_event','security_control_event','manual_attachment')),source_domain text not null,source_ref text not null,integrity_hash text,sensitivity text not null default 'internal',quality text not null check(quality in('authoritative','derived','reconstructed','partial','unknown')),safe_summary text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(investigation_id is not null or alert_id is not null));
create table public.security_investigation_hypotheses(id uuid primary key default gen_random_uuid(),investigation_id uuid not null references public.security_investigations(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,hypothesis text not null,evidence_for jsonb not null default '[]',evidence_against jsonb not null default '[]',status text not null default 'open' check(status in('open','supported','weakened','rejected','confirmed')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table public.security_hunt_queries(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,description text not null,version integer not null default 1,query_definition jsonb not null,allowed_filters text[] not null default '{}',status text not null default 'draft' check(status in('draft','active','deprecated','retired')),owner_ref text not null,read_only boolean not null default true,created_at timestamptz not null default now(),unique(context,organization_id,name,version));
create table public.security_response_playbook_refs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,response_type text not null,knowledge_article_ref text not null,allowed_scope jsonb not null,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,response_type,knowledge_article_ref));
create table public.security_response_actions(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,investigation_id uuid references public.security_investigations(id) on delete restrict,alert_id uuid references public.security_alerts(id) on delete restrict,response_type text not null,target_ref text not null,state text not null default 'proposed' check(state in('proposed','validating','awaiting_approval','approved','executing','completed','failed','reverted')),reason text not null,evidence_refs jsonb not null,policy_decision_ref text,action_request_id uuid references public.copilot_action_requests(id) on delete set null,approval_ref text,emergency boolean not null default false,verification_state text not null default 'pending' check(verification_state in('pending','verified','failed','not_supported')),verification_ref text,requested_by uuid references auth.users(id),requested_at timestamptz not null default now(),completed_at timestamptz,check(investigation_id is not null or alert_id is not null));
create table public.security_incident_candidates(id uuid primary key default gen_random_uuid(),investigation_id uuid not null references public.security_investigations(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,summary text not null,affected_refs jsonb not null,evidence_summary text not null,status text not null default 'candidate' check(status in('candidate','promoted','dismissed')),incident_id uuid references public.operational_incidents(id) on delete set null,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.security_domain_links(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,investigation_id uuid references public.security_investigations(id) on delete cascade,alert_id uuid references public.security_alerts(id) on delete cascade,domain text not null check(domain in('identity_governance','API_gateway','integration_hub','vendor_management','data_governance','AI_governance','automation_center','change_management','enterprise_risk','business_continuity','enterprise_architecture','NOC','incident_management')),entity_ref text not null,relationship text not null,evidence_ref text,created_at timestamptz not null default now(),check(investigation_id is not null or alert_id is not null));
create table public.security_soc_jobs(id uuid primary key default gen_random_uuid(),context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,job_type text not null check(job_type in('ingestion','source_health','detection_evaluation','correlation','alert_routing','investigation_enrichment','response_verification','analytics_refresh')),priority integer not null default 50,status text not null default 'queued' check(status in('queued','running','completed','failed','dead_letter')),payload_ref jsonb not null default '{}',attempt_count integer not null default 0,max_attempts integer not null default 5,available_at timestamptz not null default now(),lease_expires_at timestamptz,error_message text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.security_soc_audit_events(id bigint generated always as identity primary key,context public.security_soc_context not null,organization_id uuid references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),action text not null,resource_type text not null,resource_id text,reason text,correlation_id text not null default gen_random_uuid()::text,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());

create function public.prevent_security_soc_history_rewrite() returns trigger language plpgsql set search_path=public as $$begin raise exception 'SECURITY_SOC_HISTORY_IMMUTABLE';end$$;
create trigger security_detection_versions_immutable before update or delete on public.security_detection_rule_versions for each row execute function public.prevent_security_soc_history_rewrite();
create trigger security_timeline_immutable before update or delete on public.security_investigation_timeline for each row execute function public.prevent_security_soc_history_rewrite();
create trigger security_soc_audit_immutable before update or delete on public.security_soc_audit_events for each row execute function public.prevent_security_soc_history_rewrite();
revoke all on function public.prevent_security_soc_history_rewrite() from public,anon,authenticated;grant execute on function public.prevent_security_soc_history_rewrite() to service_role;

create unique index security_events_source_dedup_idx on public.security_events(source_domain,source_ref,source_event_id) where source_event_id is not null;
create index security_events_soc_timeline_idx on public.security_events(soc_context,organization_id,event_time desc,id);
create index security_sources_health_idx on public.security_event_sources(context,organization_id,status,last_event_at);
create index security_detection_rules_board_idx on public.security_detection_rules(context,organization_id,status,severity);
create index security_matches_time_idx on public.security_detection_matches(organization_id,matched_at desc);
create index security_alerts_queue_idx on public.security_alerts(context,organization_id,status,priority,detected_at desc);
create index security_correlations_time_idx on public.security_correlated_events(context,organization_id,status,last_seen desc);
create index security_investigations_queue_idx on public.security_investigations(context,organization_id,status,severity,started_at desc);
create index security_investigation_timeline_idx on public.security_investigation_timeline(investigation_id,event_time,id);
create index security_suppressions_expiry_idx on public.security_alert_suppressions(context,organization_id,status,expires_at);
create index security_response_queue_idx on public.security_response_actions(context,organization_id,state,requested_at);
create index security_soc_jobs_queue_idx on public.security_soc_jobs(status,priority,available_at,lease_expires_at);
create index security_soc_audit_lookup_idx on public.security_soc_audit_events(context,organization_id,created_at desc);

