insert into public.security_detection_rule_versions(rule_id,organization_id,version,rule_definition,data_requirements,suppression_policy,evaluator_version,change_reason)
select id,null,1,case rule_key
 when 'auth_failure_spread' then '{"primitive":"threshold","conditions":[{"primitive":"count","field":"auth_failure"},{"primitive":"distinct_count","field":"actor_identity_ref"}],"threshold":20,"windowSeconds":300}'::jsonb
 when 'privilege_then_critical_action' then '{"primitive":"sequence","steps":[{"primitive":"equals","field":"privilege_granted"},{"primitive":"equals","field":"critical_action"}],"windowSeconds":900}'::jsonb
 when 'break_glass_out_of_scope' then '{"primitive":"scope_match","field":"break_glass_scope"}'::jsonb
 when 'revoked_access_still_active' then '{"primitive":"sequence","steps":[{"primitive":"equals","field":"access_revoked"},{"primitive":"equals","field":"access_observed"}],"windowSeconds":3600}'::jsonb
 when 'api_authorization_failure_pattern' then '{"primitive":"threshold","conditions":[{"primitive":"count","field":"authorization_failure"}],"threshold":30,"windowSeconds":300}'::jsonb
 else '{"primitive":"threshold","conditions":[{"primitive":"count","field":"webhook_replay"}],"threshold":2,"windowSeconds":300}'::jsonb end,
case when rule_key='privilege_then_critical_action' then '["identity_governance","security_audit"]'::jsonb when rule_key='webhook_replay_candidate' then '["integration_hub"]'::jsonb else jsonb_build_array(split_part(rule_key,'_',1)) end,
'{"critical_signals_never_silently_suppressed":true}'::jsonb,'soc-dsl-v1','phase94_initial_testing_version'
from public.security_detection_rules where context='platform_soc' and organization_id is null and rule_key in('auth_failure_spread','privilege_then_critical_action','break_glass_out_of_scope','revoked_access_still_active','api_authorization_failure_pattern','webhook_replay_candidate')
on conflict(rule_id,version) do nothing;

