('platform_soc',null,'Terminated identities activity','Atividade após término ou revogação autoritativa.',1,'{"eventTypes":["auth","session","access_change"],"requires":"authoritative_lifecycle_context"}','{identity,tenant,time,event_type}','active','Security Operations',true),
('platform_soc',null,'Vendor access review','Acessos de terceiros por sistema e escopo.',1,'{"eventTypes":["vendor_access","data_access","integration"],"groupBy":["vendor_ref","target_entity_ref"]}','{vendor,service,tenant,time,event_type}','active','Security Operations',true),
('platform_soc',null,'Sensitive export activity','Exportações de dados sensíveis com propósito e contexto.',1,'{"eventTypes":["data_export"],"requires":"data_classification"}','{identity,service,tenant,time,event_type}','active','Security Operations',true)
on conflict(context,organization_id,name,version) do update set description=excluded.description,query_definition=excluded.query_definition,allowed_filters=excluded.allowed_filters,status=excluded.status,read_only=true;

create view public.security_soc_overview with(security_invoker=true) as select context,organization_id,count(*) filter(where status not in('closed','resolved','suppressed')) open_alerts,count(*) filter(where severity='critical' and status not in('closed','resolved','suppressed')) critical_alerts,count(*) filter(where status='investigating') investigating_alerts,count(*) filter(where disposition='confirmed_security_incident') confirmed_security_incidents from public.security_alerts group by context,organization_id;
create view public.fact_security_alerts with(security_invoker=true) as select context,organization_id,date_trunc('hour',detected_at) bucket_at,severity,status,disposition,count(*) alert_count from public.security_alerts group by context,organization_id,date_trunc('hour',detected_at),severity,status,disposition;
create view public.fact_security_investigations with(security_invoker=true) as select context,organization_id,date_trunc('day',started_at) bucket_at,status,severity,investigation_type,count(*) investigation_count from public.security_investigations group by context,organization_id,date_trunc('day',started_at),status,severity,investigation_type;
create view public.fact_security_response_actions with(security_invoker=true) as select context,organization_id,date_trunc('day',requested_at) bucket_at,response_type,state,verification_state,count(*) action_count from public.security_response_actions group by context,organization_id,date_trunc('day',requested_at),response_type,state,verification_state;

do $$declare t text;begin foreach t in array array['security_events','security_soc_member_permissions','security_event_sources','security_source_health','security_detection_rules','security_detection_rule_versions','security_detection_test_runs','security_detection_coverage','security_detection_matches','security_correlated_events','security_correlation_event_links','security_alerts','security_alert_suppressions','security_investigations','security_investigation_alerts','security_investigation_timeline','security_evidence_refs','security_investigation_hypotheses','security_hunt_queries','security_response_playbook_refs','security_response_actions','security_incident_candidates','security_domain_links','security_soc_jobs','security_soc_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
do $$declare v text;begin foreach v in array array['security_soc_overview','fact_security_alerts','fact_security_investigations','fact_security_response_actions'] loop execute format('revoke all on public.%I from public,anon,authenticated',v);execute format('grant select on public.%I to service_role',v);end loop;end$$;

